// Deja el prospecto en una forma estable antes de decidir nada sobre el.
// El webhook es una direccion publica: no se puede dar por hecho que los campos lleguen,
// ni que lleguen escritos como los manda el formulario.

const cuerpo = $input.item.json.body ?? $input.item.json;
const texto = (v) => String(v ?? '').trim();

const correo = texto(cuerpo.email || cuerpo.correo).toLowerCase();
const dominio = correo.includes('@') ? correo.split('@').pop() : '';

// El formulario manda el presupuesto como rango. Si el webhook lo llaman desde otro lado
// puede venir un numero suelto ("1800", "USD 1.800"): se acepta igual y se convierte al rango.
const crudo = texto(cuerpo.presupuesto).toLowerCase();
let presupuesto = ['menos_500', '500_1500', 'mas_1500'].includes(crudo) ? crudo : '';
if (!presupuesto && /\d/.test(crudo)) {
  const n = Number(crudo.replace(/[^\d]/g, '')) || 0;
  presupuesto = n >= 1500 ? 'mas_1500' : n >= 500 ? '500_1500' : 'menos_500';
}

const urgencias = { ya: 'ya', inmediata: 'ya', mes: 'mes', este_mes: 'mes', explorando: 'explorando' };
const urgencia = urgencias[texto(cuerpo.urgencia).toLowerCase()] ?? 'explorando';

// Telefono colombiano: se guarda solo con digitos para que el CRM no tenga tres formatos
// del mismo numero y los duplicados se puedan detectar.
const telefono = texto(cuerpo.telefono).replace(/[^\d]/g, '').replace(/^57/, '');

const errores = [];
if (texto(cuerpo.nombre).length < 2) errores.push('nombre');
// Validacion de correo a proposito simple: la unica prueba de que un correo existe es
// escribirle. Aqui solo se descarta lo que claramente no es una direccion.
if (!/^[^@\s]+@[^@\s.]+\.[^@\s]{2,}$/.test(correo)) errores.push('email');
if (telefono.length < 10) errores.push('telefono');

return {
  json: {
    nombre: texto(cuerpo.nombre),
    correo,
    dominio,
    telefono,
    presupuesto,
    urgencia,
    origen: texto(cuerpo.origen) || 'desconocido',
    recibido: new Date().toISOString(),
    valido: errores.length === 0,
    errores,
  },
};

// Calcula la temperatura del prospecto. El puntaje esta a la vista a proposito: un comercial
// tiene que poder discutir por que un lead quedo frio, y eso no se puede hacer con una caja negra.

const lead = $('Normalizar').item.json;
const dns = $input.item.json;

// dns.google responde Status 0 y una lista Answer cuando el dominio tiene servidores de correo.
// Si la consulta fallo, el item trae el error en vez de la respuesta: eso es "no sabemos",
// que no es lo mismo que "el dominio no sirve". Por eso hay tres estados y no dos.
const consultaOk = dns && typeof dns.Status === 'number';
const recibeCorreo = consultaOk && Array.isArray(dns.Answer) && dns.Answer.length > 0;
const dominioVerificado = consultaOk ? recibeCorreo : null;

const gratuitos = ['gmail.com', 'hotmail.com', 'hotmail.es', 'outlook.com', 'outlook.es',
  'yahoo.com', 'yahoo.es', 'icloud.com', 'live.com', 'proton.me', 'protonmail.com'];
const corporativo = Boolean(lead.dominio) && !gratuitos.includes(lead.dominio);

const porPresupuesto = { mas_1500: 40, '500_1500': 25, menos_500: 10 };
const porUrgencia = { ya: 30, mes: 20, explorando: 0 };

let puntos = 0;
const porque = [];

const p = porPresupuesto[lead.presupuesto] ?? 0;
if (p) { puntos += p; porque.push(`presupuesto ${lead.presupuesto}: +${p}`); }

const u = porUrgencia[lead.urgencia] ?? 0;
if (u) { puntos += u; porque.push(`urgencia ${lead.urgencia}: +${u}`); }

if (corporativo) { puntos += 20; porque.push('correo corporativo: +20'); }

let temperatura = puntos >= 65 ? 'caliente' : puntos >= 35 ? 'tibio' : 'frio';

// Un dominio que comprobadamente no recibe correo casi siempre es un error de digitacion o un
// dato inventado. Restar puntos no sirve: un presupuesto alto los compensa y el lead sigue
// saliendo caliente. Por eso es un tope y no una resta: no se manda a un comercial a perseguir
// a alguien a quien no le vamos a poder escribir.
if (dominioVerificado === false) {
  porque.push('el dominio no recibe correo: no puede pasar de tibio');
  if (temperatura === 'caliente') temperatura = 'tibio';
}

// Anti-duplicados sin base de datos: n8n conserva datos estaticos del workflow entre ejecuciones.
// En produccion esto lo resuelve el CRM con una restriccion unica sobre el correo; aqui alcanza
// para dejar demostrado que el caso esta contemplado y no se crean dos fichas del mismo cliente.
//
// Solo cuenta como repetido dentro de una ventana de tiempo. Quien escribio hace tres meses no
// esta insistiendo: es una oportunidad nueva, y tratarla como duplicado la manda a actualizar un
// registro viejo en vez de abrir el ciclo otra vez.
const VENTANA_MS = 24 * 60 * 60 * 1000;
const ahora = Date.now();
const memoria = $getWorkflowStaticData('global');
memoria.vistos = memoria.vistos ?? {};

const previo = memoria.vistos[lead.correo];
const vigente = previo && (ahora - previo.ultimo) < VENTANA_MS;
const veces = vigente ? previo.veces + 1 : 1;
memoria.vistos[lead.correo] = { veces, ultimo: ahora };

// La memoria no crece para siempre: se olvidan los correos fuera de la ventana.
for (const [correo, dato] of Object.entries(memoria.vistos)) {
  if (ahora - dato.ultimo >= VENTANA_MS) delete memoria.vistos[correo];
}

return {
  json: {
    ...lead,
    puntos,
    temperatura,
    porque,
    corporativo,
    dominioVerificado,
    veces,
    repetido: veces > 1,
  },
};
